public static String appx(String word1, String word2) {
    int commonCount = 0;
    for (int i = 0; i < word1.length(); i++) {
        char c1 = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            if (c1 == word2.charAt(j)) {
                commonCount++;
                break;
            }
        }
    }
    int sumLengths = word1.length() + word2.length();
    int numerator = commonCount;
    int denominator = sumLengths;

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
