public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;

    int sum = 0;
    for (int num : nums) sum += num;

    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum(subset) / k == sum / n
    // => sum(subset) * n == sum * k
    // => sum(subset) == sum * k / n
    // So sum * k must be divisible by n.

    // To optimize, we can use the fact that if a subset of size k works,
    // then a subset of size n-k also works (the complement).
    // So we only need to check k from 1 to n/2.

    // Also, we can use a DP approach: dp[k][s] = true if we can form a subset of size k with sum s.
    // But s can be large. However, we can note that the target sum for size k is sum * k / n.
    // So we only need to check if that specific sum is achievable.

    // Alternative: use a set-based DP for each k, storing achievable sums.
    // Since n is at most 16 (in typical problems), we can use bitset or HashSet.

    // Let's use a HashSet for each k.
    // dp[k] is a set of sums achievable with k elements.

    // But to save memory, we can iterate k from 1 to n/2 and for each k, check if sum*k % n == 0,
    // and if so, check if sum*k/n is in dp[k].

    // Initialize: dp[0] = {0}
    // For each num, update dp in reverse order of k.

    // Since n is small (<= 16), we can use a list of HashSets.

    int maxK = n / 2;
    java.util.Set<Integer>[] dp = new java.util.Set[maxK + 1];
    for (int i = 0; i <= maxK; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        // Update in reverse order to avoid using the same element twice
        for (int k = maxK; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        if (sum * k % n == 0) {
            int target = sum * k / n;
            if (dp[k].contains(target)) {
                return true;
            }
        }
    }

    return false;
}
