public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // The target value to make all elements equal is the average of the array.
    // Sum of arr = sum_{i=0}^{n-1} (2*i + 1) = 2 * (n-1)*n/2 + n = n*(n-1) + n = n^2
    // Average = n^2 / n = n
    // So we need to make all elements equal to n.
    // The number of operations is the sum of positive differences (or negative differences) from the target.
    // Since the array is symmetric around the average, we can compute the sum of (n - arr[i]) for i where arr[i] < n.
    // arr[i] = 2*i + 1 < n  =>  2*i + 1 < n  =>  i < (n-1)/2
    // For each such i, the difference is n - (2*i + 1).
    // Let's compute this sum.

    // Alternatively, we can derive a closed form.
    // For n = 3: target = 3, arr = [1,3,5], differences: 3-1=2, 3-3=0, 5-3=2. Sum of positive diffs = 2.
    // For n = 6: target = 6, arr = [1,3,5,7,9,11], differences: 6-1=5, 6-3=3, 6-5=1, 7-6=1, 9-6=3, 11-6=5. Sum of positive diffs = 5+3+1 = 9.

    // The sum of (n - (2*i + 1)) for i from 0 to floor((n-2)/2) (i.e., while 2*i+1 < n)
    // Let k = number of terms where 2*i+1 < n.
    // If n is odd, n = 2m+1, then 2*i+1 < 2m+1 => i < m, so i from 0 to m-1, k = m = (n-1)/2.
    // Sum = sum_{i=0}^{m-1} (2m+1 - 2*i - 1) = sum_{i=0}^{m-1} (2m - 2*i) = 2 * sum_{i=0}^{m-1} (m - i) = 2 * (m + (m-1) + ... + 1) = 2 * m*(m+1)/2 = m*(m+1).
    // For n=3, m=1, result = 1*2 = 2. Correct.
    // For n=5, m=2, result = 2*3 = 6. Let's verify: arr=[1,3,5,7,9], target=5, diffs: 4,2,0,2,4, sum of positive = 4+2=6. Correct.

    // If n is even, n = 2m, then 2*i+1 < 2m => i < (2m-1)/2 = m - 0.5, so i from 0 to m-1, k = m = n/2.
    // Sum = sum_{i=0}^{m-1} (2m - 2*i - 1) = sum_{i=0}^{m-1} (2m - 1 - 2*i)
    // = m*(2m-1) - 2 * sum_{i=0}^{m-1} i = m*(2m-1) - 2 * (m-1)*m/2 = m*(2m-1) - m*(m-1) = m*(2m-1 - m + 1) = m*(m) = m^2.
    // For n=6, m=3, result = 9. Correct.
    // For n=4, m=2, result = 4. Let's verify: arr=[1,3,5,7], target=4, diffs: 3,1,1,3, sum of positive = 3+1=4. Correct.

    // So:
    // If n is odd: n = 2m+1, m = (n-1)/2, result = m*(m+1)
    // If n is even: n = 2m, m = n/2, result = m*m

    if (n % 2 == 1) {
        int m = (n - 1) / 2;
        return m * (m + 1);
    } else {
        int m = n / 2;
        return m * m;
    }
}
