private int dfs(String s, int start, Set<String> used) {
    if (start == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String sub = s.substring(start, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int count = 1 + dfs(s, end, used);
            max = Math.max(max, count);
            used.remove(sub);
        }
    }
    return max;
}
