private static boolean isSteppingNumber(int num) {
    if (num < 10) {
        return true;
    }
    int prevDigit = num % 10;
    num /= 10;
    while (num > 0) {
        int currDigit = num % 10;
        if (Math.abs(currDigit - prevDigit) != 1) {
            return false;
        }
        prevDigit = currDigit;
        num /= 10;
    }
    return true;
