public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];

    int index = 0;
    // There are rows + cols - 1 diagonals
    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Traverse from bottom-left to top-right
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Traverse from top-right to bottom-left
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (c >= 0 && r < rows) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}
