public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) {
        return result;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    char[] digits = new char[n];
    generate(n, 0, digits, pairs, result, true);
    return result;
}

private static void generate(int n, int depth, char[] digits, char[][] pairs, List<String> result, boolean isLeading) {
    if (depth == n / 2) {
        if (n % 2 == 1) {
            for (char c : new char[]{'0', '1', '8'}) {
                digits[depth] = c;
                result.add(new String(digits));
            }
        } else {
            result.add(new String(digits));
        }
        return;
    }
    for (char[] pair : pairs) {
        if (isLeading && pair[0] == '0') {
            continue;
        }
        digits[depth] = pair[0];
        digits[n - 1 - depth] = pair[1];
        generate(n, depth + 1, digits, pairs, result, false);
    }
}
